import { readFileSync, writeFileSync } from 'fs';

const p = 'tools/pcb_templates/export.mjs';
let s = readFileSync(p, 'utf8');
const neu = readFileSync('tools/pcb_templates/_hand_digital.mjs', 'utf8').trimEnd() + '\n\n';

if (s.includes('function handLayoutLabDigital(doc)')) {
  const startFn = s.indexOf('function handLayoutLabDigital(doc)');
  let cStart = startFn;
  for (;;) {
    const chunk = s.slice(Math.max(0, cStart - 500), cStart);
    const m = chunk.match(/(\/\*\*[\s\S]*?数字逻辑[\s\S]*?\*\/)\s*$/);
    if (!m) break;
    cStart -= m[0].length;
  }
  const end = s.indexOf('function handLayoutLab', startFn + 10);
  const end2 = s.indexOf('\nfunction main(', startFn);
  const cut = end > 0 && (end2 < 0 || end < end2) ? end : end2;
  if (cut < 0) {
    console.error('cannot find end of handLayoutLabDigital');
    process.exit(1);
  }
  s = s.slice(0, cStart) + neu + s.slice(cut);
} else {
  const anchor = s.indexOf('\nfunction main()');
  if (anchor < 0) {
    console.error('no main');
    process.exit(1);
  }
  s = s.slice(0, anchor) + '\n\n' + neu + s.slice(anchor);
}

// wire main
if (!s.includes("id === 'lab_digital'")) {
  s = s.replace(
    "} else if (id === 'lab_analog_ic') {\n      doc.footprints = doc.footprints.filter(f => !!f.schematicCompId);\n      doc.tracks = [];\n      doc.vias = [];\n      doc.zones = [];\n      route = handLayoutLabAnalogIc(doc);\n    } else {",
    "} else if (id === 'lab_analog_ic') {\n      doc.footprints = doc.footprints.filter(f => !!f.schematicCompId);\n      doc.tracks = [];\n      doc.vias = [];\n      doc.zones = [];\n      route = handLayoutLabAnalogIc(doc);\n    } else if (id === 'lab_digital') {\n      doc.footprints = doc.footprints.filter(f => !!f.schematicCompId);\n      doc.tracks = [];\n      doc.vias = [];\n      doc.zones = [];\n      route = handLayoutLabDigital(doc);\n    } else {"
  );
}
if (!s.includes("'lab_digital'")) {
  // handLabs array
  s = s.replace(
    "const handLabs = ['lab_power', 'lab_amp', 'lab_filter', 'lab_51_led', 'lab_uart', 'lab_passive', 'lab_discrete', 'lab_analog_ic'];",
    "const handLabs = ['lab_power', 'lab_amp', 'lab_filter', 'lab_51_led', 'lab_uart', 'lab_passive', 'lab_discrete', 'lab_analog_ic', 'lab_digital'];"
  );
} else if (!s.includes("'lab_analog_ic', 'lab_digital'")) {
  s = s.replace(
    "'lab_analog_ic'];",
    "'lab_analog_ic', 'lab_digital'];"
  );
}

writeFileSync(p, s);
console.log({
  nFn: (s.match(/function handLayoutLabDigital/g) || []).length,
  wired: s.includes("route = handLayoutLabDigital"),
  handLabs: s.includes("'lab_digital']") || s.includes("'lab_digital',")
});
